/* Generated by agentic-proofkit json-report-cli-adapter-source.
 * Public contract: local generated source that drives the Proofkit CLI/JSON ABI.
 * Non-claim: this file does not publish an agentic-proofkit package SDK.
 */

import { spawnSync } from "node:child_process";
import { closeSync, fstatSync, fsyncSync, lstatSync, mkdirSync, openSync, readSync, realpathSync, renameSync, unlinkSync, writeFileSync } from "node:fs";
import { randomUUID } from "node:crypto";
import { basename, dirname, isAbsolute, relative, resolve, sep } from "node:path";

const defaultMaxBuffer = 64 * 1024 * 1024;
const defaultMaxInputBytes = 32 * 1024 * 1024;
const maxDiagnosticRunes = 512;
const maxJsonNestingDepth = 512;
const unsafeScalarRanges: readonly (readonly [number, number, number])[] = [
  [0x000000, 0x00001f, 1], [0x00007f, 0x00009f, 1],
  [0x0000ad, 0x000600, 1363], [0x000601, 0x000605, 1],
  [0x00061c, 0x0006dd, 193], [0x00070f, 0x000890, 385],
  [0x000891, 0x0008e2, 81], [0x00180e, 0x00200b, 2045],
  [0x00200c, 0x00200f, 1], [0x002028, 0x002028, 1],
  [0x002029, 0x002029, 1], [0x00202a, 0x00202e, 1],
  [0x002060, 0x002064, 1], [0x002066, 0x00206f, 1],
  [0x00feff, 0x00fff9, 250], [0x00fffa, 0x00fffb, 1],
  [0x0110bd, 0x0110cd, 16], [0x013430, 0x01343f, 1],
  [0x01bca0, 0x01bca3, 1], [0x01d173, 0x01d17a, 1],
  [0x0e0001, 0x0e0020, 31], [0x0e0021, 0x0e007f, 1],
];

export type ProofkitJsonValue =
  | null
  | boolean
  | number
  | string
  | readonly ProofkitJsonValue[]
  | { readonly [key: string]: ProofkitJsonValue };

export type ProofkitJsonRecord = { readonly [key: string]: unknown };

export type ProofkitReportRecord = ProofkitJsonRecord & {
  readonly diagnostics: readonly ProofkitJsonRecord[];
  readonly nonClaims: readonly string[];
  readonly reportId: string;
  readonly reportKind: string;
  readonly ruleResults: readonly ProofkitJsonRecord[];
  readonly schemaVersion: 1;
  readonly state: "blocked" | "failed" | "passed";
  readonly summary: ProofkitJsonRecord;
};

export interface ProofkitJsonReportCliFlag<Key extends string = string> {
  readonly flag: string;
  readonly key: Key;
  readonly required?: boolean;
}

export interface ProofkitJsonReportCliParseConfig<Key extends string = string> {
  readonly flags: readonly ProofkitJsonReportCliFlag<Key>[];
  readonly helpText?: string;
  readonly exitHelp?: (code: number) => never;
  readonly missingRequiredArgumentsMessage?: (flags: readonly string[]) => string;
  readonly missingValueMessage?: (flag: string) => string;
  readonly unknownArgumentMessage?: (argument: string) => string;
  readonly writeHelp?: (text: string) => void;
}

export type ProofkitJsonReportCliOptions<Key extends string = string> = {
  readonly outputPath: string | null;
} & { readonly [K in Key]: string | null };

export interface ProofkitReportInputReadOptions {
  readonly failureMessagePrefix?: string;
  readonly maxInputBytes?: number;
}

export interface ProofkitJsonReportOutputOptions {
  readonly cwd?: string;
  readonly jsonLayout?: "pretty" | "compact";
  readonly writeStdout?: (text: string) => void;
}

export interface ProofkitCommandRunOptions {
  readonly binaryPath: string;
  readonly cwd: string;
  readonly env?: Readonly<Record<string, string | undefined>>;
  readonly inputMode?: "none" | "required";
  readonly jsonLayout?: "pretty" | "compact";
  readonly maxBuffer?: number;
}

export interface ProofkitProcessResult {
  readonly status: number | null;
  readonly stdout: string;
  readonly stderr: string;
}

export type ProofkitJsonCommandResult<T = unknown> = ProofkitProcessResult & {
  readonly value: T;
};

export type ProofkitTextCommandResult = ProofkitProcessResult & {
  readonly text: string;
};

export function isProofkitJsonRecord(value: unknown): value is ProofkitJsonRecord {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function proofkitStableJsonValue(value: unknown): ProofkitJsonValue {
  return stableJsonValueAtDepth(value, 1, new WeakSet<object>());
}

function stableJsonValueAtDepth(value: unknown, depth: number, active: WeakSet<object>): ProofkitJsonValue {
  if (depth > maxJsonNestingDepth) {
    throw new Error("stable JSON value exceeds nesting depth limit");
  }
  if (value === null || typeof value === "boolean") {
    return value;
  }
  if (typeof value === "string") {
    return assertProofkitScalarString(value);
  }
  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      throw new Error("stable JSON value must not contain non-finite numbers");
    }
    if (Number.isInteger(value) && !Number.isSafeInteger(value)) {
      throw new Error("stable JSON value must not contain unsafe integer numbers");
    }
    return value;
  }
  if (Array.isArray(value)) {
    if (active.has(value)) {
      throw new Error("stable JSON value must not contain cycles");
    }
    active.add(value);
    const arrayKeys = Reflect.ownKeys(value);
    if (arrayKeys.some((key) =>
      typeof key === "symbol" ||
      (key !== "length" && (!/^(?:0|[1-9][0-9]*)$/u.test(key) || Number(key) >= value.length))
    )) {
      throw new Error("stable JSON arrays must not contain custom properties");
    }
    const output: ProofkitJsonValue[] = [];
    for (let index = 0; index < value.length; index += 1) {
      const descriptor = Object.getOwnPropertyDescriptor(value, String(index));
      if (descriptor === undefined) {
        throw new Error("stable JSON arrays must be dense");
      }
      if (!("value" in descriptor) || !descriptor.enumerable) {
        throw new Error("stable JSON arrays must contain enumerable own data elements only");
      }
      output.push(stableJsonValueAtDepth(descriptor.value, depth + 1, active));
    }
    active.delete(value);
    return output;
  }
  if (typeof value === "object") {
    const record = value as Record<string, unknown>;
    const prototype = Object.getPrototypeOf(record);
    if (prototype !== Object.prototype && prototype !== null) {
      throw new Error("stable JSON objects must use a plain or null prototype");
    }
    if (active.has(record)) {
      throw new Error("stable JSON value must not contain cycles");
    }
    active.add(record);
    const output = Object.create(null) as Record<string, ProofkitJsonValue>;
    const ownKeys = Reflect.ownKeys(record);
    if (ownKeys.some((key) => typeof key === "symbol")) {
      throw new Error("stable JSON objects must not contain symbol keys");
    }
    for (const key of (ownKeys as string[]).map(assertProofkitScalarString).sort(compareProofkitScalarStrings)) {
      if (key.length === 0 || key.includes("\0")) {
        throw new Error("stable JSON object keys must be non-empty text");
      }
      const descriptor = Object.getOwnPropertyDescriptor(record, key);
      if (descriptor === undefined || !("value" in descriptor) || !descriptor.enumerable) {
        throw new Error("stable JSON objects must contain enumerable own data properties only");
      }
      Object.defineProperty(output, key, {
        configurable: true,
        enumerable: true,
        value: stableJsonValueAtDepth(descriptor.value, depth + 1, active),
        writable: true,
      });
    }
    active.delete(record);
    return output;
  }
  throw new Error("stable JSON value must be JSON-serializable");
}

export function proofkitStableJsonString(value: unknown, layout: "pretty" | "compact" = "pretty"): string {
  return writeProofkitStableJson(proofkitStableJsonValue(value), 0, layout) + "\n";
}

function writeProofkitStableJson(value: ProofkitJsonValue, depth: number, layout: "pretty" | "compact"): string {
  if (value === null) return "null";
  if (typeof value === "boolean") return value ? "true" : "false";
  if (typeof value === "number") return JSON.stringify(value);
  if (typeof value === "string") return quoteProofkitScalarString(value);
  const pretty = layout === "pretty";
  if (Array.isArray(value)) {
    if (value.length === 0) return "[]";
    const separator = pretty ? ",\n" : ",";
    const prefix = pretty ? "\n" : "";
    const suffix = pretty ? "\n" + "  ".repeat(depth) : "";
    const entries = value.map((entry) => (pretty ? "  ".repeat(depth + 1) : "") + writeProofkitStableJson(entry, depth + 1, layout));
    return "[" + prefix + entries.join(separator) + suffix + "]";
  }
  const record = value as Readonly<Record<string, ProofkitJsonValue>>;
  const keys = Object.keys(record).sort(compareProofkitScalarStrings);
  if (keys.length === 0) return "{}";
  const separator = pretty ? ",\n" : ",";
  const prefix = pretty ? "\n" : "";
  const suffix = pretty ? "\n" + "  ".repeat(depth) : "";
  const entries = keys.map((key) =>
    (pretty ? "  ".repeat(depth + 1) : "") + quoteProofkitScalarString(key) + (pretty ? ": " : ":") + writeProofkitStableJson(record[key] as ProofkitJsonValue, depth + 1, layout)
  );
  return "{" + prefix + entries.join(separator) + suffix + "}";
}

function assertProofkitScalarString(value: string): string {
	if (!isProofkitScalarString(value)) {
		throw new Error("stable JSON strings must contain only Unicode scalar values");
	}
	return value;
}

function isProofkitScalarString(value: string): boolean {
  for (let index = 0; index < value.length; index += 1) {
    const unit = value.charCodeAt(index);
    if (unit >= 0xd800 && unit <= 0xdbff) {
      const low = value.charCodeAt(index + 1);
      if (!(low >= 0xdc00 && low <= 0xdfff)) {
        return false;
      }
      index += 1;
    } else if (unit >= 0xdc00 && unit <= 0xdfff) {
      return false;
    }
  }
  return true;
}

function compareProofkitScalarStrings(left: string, right: string): number {
  let leftIndex = 0;
  let rightIndex = 0;
  while (leftIndex < left.length && rightIndex < right.length) {
    const leftScalar = left.codePointAt(leftIndex) as number;
    const rightScalar = right.codePointAt(rightIndex) as number;
    if (leftScalar !== rightScalar) return leftScalar - rightScalar;
    leftIndex += leftScalar > 0xffff ? 2 : 1;
    rightIndex += rightScalar > 0xffff ? 2 : 1;
  }
  if (leftIndex < left.length) return 1;
  if (rightIndex < right.length) return -1;
  return 0;
}

function isProofkitUnsafeScalar(value: number): boolean {
  let low = 0;
  let high = unsafeScalarRanges.length;
  while (low < high) {
    const middle = Math.floor((low + high) / 2);
    if ((unsafeScalarRanges[middle] as readonly [number, number, number])[1] < value) low = middle + 1;
    else high = middle;
  }
  if (low === unsafeScalarRanges.length) return false;
  const [start, end, step] = unsafeScalarRanges[low] as readonly [number, number, number];
  return value >= start && value <= end && (value - start) % step === 0;
}

function quoteProofkitScalarString(value: string): string {
  assertProofkitScalarString(value);
  let output = "\"";
  for (const character of value) {
    const scalar = character.codePointAt(0) as number;
    switch (scalar) {
      case 0x22: output += "\\\""; break;
      case 0x5c: output += "\\\\"; break;
      case 0x08: output += "\\b"; break;
      case 0x09: output += "\\t"; break;
      case 0x0a: output += "\\n"; break;
      case 0x0c: output += "\\f"; break;
      case 0x0d: output += "\\r"; break;
      default: output += isProofkitUnsafeScalar(scalar) ? proofkitUnicodeEscape(scalar) : character;
    }
  }
  return output + "\"";
}

function proofkitUnicodeEscape(value: number): string {
  if (value <= 0xffff) return "\\u" + value.toString(16).padStart(4, "0");
  const adjusted = value - 0x10000;
  const high = 0xd800 + (adjusted >> 10);
  const low = 0xdc00 + (adjusted & 0x3ff);
  return "\\u" + high.toString(16) + "\\u" + low.toString(16);
}

function decodeProofkitUTF8(bytes: Uint8Array, fixedLabel: string): string {
  try {
    return new TextDecoder("utf-8", {fatal: true}).decode(bytes);
  } catch {
    throw new Error(fixedLabel + " is not valid UTF-8");
  }
}

export function formatProofkitCliError(error: unknown): string {
  return redactDiagnosticValue(error instanceof Error ? error.message : String(error));
}

function redactDiagnosticValue(value: string): string {
	if (!isProofkitScalarString(value) || containsProofkitUnsafeScalar(value) || containsProofkitSecretLikeValue(value)) {
		return "<redacted-diagnostic-value>";
	}
	return truncateDiagnosticValue(value);
}

function truncateDiagnosticValue(value: string): string {
  const runes = [...value];
  if (runes.length <= maxDiagnosticRunes) {
    return value;
  }
  return runes.slice(0, maxDiagnosticRunes).join("") + "...<truncated-diagnostic>";
}

function containsProofkitUnsafeScalar(value: string): boolean {
  for (const character of value) {
		if (isProofkitUnsafeScalar(character.codePointAt(0) as number)) return true;
  }
	return false;
}

const proofkitSecretPattern = new RegExp(["authorization(?:\\\\*[\"'])?(?:[\\t\\n\\v\\f\\r \\x85\\p{Zs}\\p{Zl}\\p{Zp}]|\\\\+[ntrfv]|\\\\+u(?:000[9a-d]|0020|0085|00a0|202[89]))*:(?:[\\t\\n\\v\\f\\r \\x85\\p{Zs}\\p{Zl}\\p{Zp}]|\\\\+[ntrfv]|\\\\+u(?:000[9a-d]|0020|0085|00a0|202[89]))*[^\\r\\n]+|bearer(?:[\\t\\n\\v\\f\\r \\x85\\p{Zs}\\p{Zl}\\p{Zp}]|\\\\+[ntrfv]|\\\\+u(?:000[9a-d]|0020|0085|00a0|202[89]))+[A-Za-z0-9._~+/=-]{8,}|(?:access[-_]?token|api[-_]?key|pass(?:word|wd)|secret|token)(?:\\\\*[\"'])?(?:[\\t\\n\\v\\f\\r \\x85\\p{Zs}\\p{Zl}\\p{Zp}]|\\\\+[ntrfv]|\\\\+u(?:000[9a-d]|0020|0085|00a0|202[89]))*[=:](?:[\\t\\n\\v\\f\\r \\x85\\p{Zs}\\p{Zl}\\p{Zp}]|\\\\+[ntrfv]|\\\\+u(?:000[9a-d]|0020|0085|00a0|202[89]))*[^\\t\\n\\v\\f\\r \\x85\\p{Zs}\\p{Zl}\\p{Zp}]+|-----BEGIN [A-Z ]*PRIVATE KEY-----|github_pat_[A-Za-z0-9_]+|gh[pousr]_[A-Za-z0-9_]+|xox[abprs]-[A-Za-z0-9-]+|glpat-[A-Za-z0-9_-]+|eyJ[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+|sk-(?:proj-)?[A-Za-z0-9_-]{10,}", "[A-Za-z][A-Za-z0-9+.-]*://[^/\\t\\n\\v\\f\\r \\x85\\p{Zs}\\p{Zl}\\p{Zp}:@]+:[^/\\t\\n\\v\\f\\r \\x85\\p{Zs}\\p{Zl}\\p{Zp}@]+@"][0], "iu");
const proofkitURLCredentialPattern = new RegExp(["authorization(?:\\\\*[\"'])?(?:[\\t\\n\\v\\f\\r \\x85\\p{Zs}\\p{Zl}\\p{Zp}]|\\\\+[ntrfv]|\\\\+u(?:000[9a-d]|0020|0085|00a0|202[89]))*:(?:[\\t\\n\\v\\f\\r \\x85\\p{Zs}\\p{Zl}\\p{Zp}]|\\\\+[ntrfv]|\\\\+u(?:000[9a-d]|0020|0085|00a0|202[89]))*[^\\r\\n]+|bearer(?:[\\t\\n\\v\\f\\r \\x85\\p{Zs}\\p{Zl}\\p{Zp}]|\\\\+[ntrfv]|\\\\+u(?:000[9a-d]|0020|0085|00a0|202[89]))+[A-Za-z0-9._~+/=-]{8,}|(?:access[-_]?token|api[-_]?key|pass(?:word|wd)|secret|token)(?:\\\\*[\"'])?(?:[\\t\\n\\v\\f\\r \\x85\\p{Zs}\\p{Zl}\\p{Zp}]|\\\\+[ntrfv]|\\\\+u(?:000[9a-d]|0020|0085|00a0|202[89]))*[=:](?:[\\t\\n\\v\\f\\r \\x85\\p{Zs}\\p{Zl}\\p{Zp}]|\\\\+[ntrfv]|\\\\+u(?:000[9a-d]|0020|0085|00a0|202[89]))*[^\\t\\n\\v\\f\\r \\x85\\p{Zs}\\p{Zl}\\p{Zp}]+|-----BEGIN [A-Z ]*PRIVATE KEY-----|github_pat_[A-Za-z0-9_]+|gh[pousr]_[A-Za-z0-9_]+|xox[abprs]-[A-Za-z0-9-]+|glpat-[A-Za-z0-9_-]+|eyJ[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+|sk-(?:proj-)?[A-Za-z0-9_-]{10,}", "[A-Za-z][A-Za-z0-9+.-]*://[^/\\t\\n\\v\\f\\r \\x85\\p{Zs}\\p{Zl}\\p{Zp}:@]+:[^/\\t\\n\\v\\f\\r \\x85\\p{Zs}\\p{Zl}\\p{Zp}@]+@"][1], "iuy");
const proofkitEscapedSecretControls: Record<string, string> = {n: "\n", t: "\t", r: "\r", f: "\f", v: "\v", b: "\b"};
const proofkitMaxSecretDecodePasses = 16;

function decodeProofkitEscapedSecretText(value: string): string {
	const parts: string[] = [];
	for (let index = 0; index < value.length;) {
		const start = value.indexOf("\\", index);
		if (start < 0) {
			parts.push(value.slice(index));
			break;
		}
		if (start > index) parts.push(value.slice(index, start));
		let cursor = start;
		while (cursor < value.length && value[cursor] === "\\") cursor++;
		parts.push("\\".repeat(Math.floor((cursor - start) / 2)));
		if ((cursor - start) % 2 === 0) {
			index = cursor;
			continue;
		}
		if (cursor === value.length) {
			parts.push("\\");
			break;
		}
		if (hasProofkitSecretUnicodeUnit(value, cursor)) {
			const first = Number.parseInt(value.slice(cursor + 1, cursor + 5), 16);
			if (first >= 0xd800 && first <= 0xdbff) {
				const second = cursor + 5;
				if (value[second] === "\\" && hasProofkitSecretUnicodeUnit(value, second + 1)) {
					const low = Number.parseInt(value.slice(second + 2, second + 6), 16);
					if (low >= 0xdc00 && low <= 0xdfff) {
						parts.push(String.fromCodePoint(0x10000 + ((first - 0xd800) << 10) + low - 0xdc00));
						index = second + 6;
						continue;
					}
				}
			}
			parts.push(decodeProofkitSecretUnicodeScalar(first, value.slice(cursor - 1, cursor + 5)));
			index = cursor + 5;
			continue;
		}
		const suffix = value[cursor];
		if (Object.hasOwn(proofkitEscapedSecretControls, suffix)) parts.push(proofkitEscapedSecretControls[suffix]);
		else if (suffix === "/" || suffix === '"') parts.push(suffix);
		else {
			parts.push("\\");
			index = cursor;
			continue;
		}
		index = cursor + 1;
	}
	return parts.join("");
}

function hasProofkitSecretUnicodeUnit(value: string, index: number): boolean {
	if (value[index] !== "u" || index + 5 > value.length) return false;
	for (let offset = 1; offset <= 4; offset++) {
		const code = value.charCodeAt(index + offset);
		if (!((code >= 48 && code <= 57) || (code >= 65 && code <= 70) || (code >= 97 && code <= 102))) return false;
	}
	return true;
}

function decodeProofkitSecretUnicodeScalar(value: number, original: string): string {
	return value >= 0xd800 && value <= 0xdfff ? original : String.fromCodePoint(value);
}

function containsProofkitSecretLikeValue(value: string): boolean {
	let candidate = value;
	for (let depth = 0; depth <= proofkitMaxSecretDecodePasses; depth++) {
		if (matchesProofkitSecretPattern(candidate)) return true;
		const withoutUnsafe = [...candidate].filter((character) => !isProofkitUnsafeScalar(character.codePointAt(0) as number)).join("");
		if (withoutUnsafe !== candidate && matchesProofkitSecretPattern(withoutUnsafe)) return true;
		const decoded = decodeProofkitEscapedSecretText(withoutUnsafe);
		if (decoded === candidate) return false;
		if (depth === proofkitMaxSecretDecodePasses) return true;
		candidate = decoded;
	}
	return true;
}

function matchesProofkitSecretPattern(value: string): boolean {
	return proofkitSecretPattern.test(value) || hasProofkitURLCredential(value);
}

function hasProofkitURLCredential(value: string): boolean {
	for (let search = 0; search < value.length;) {
		const separator = value.indexOf("://", search);
		if (separator < 0) return false;
		let start = separator;
		while (start > 0 && isProofkitSchemeCode(value.charCodeAt(start - 1))) start--;
		while (start < separator && !isProofkitASCIILetterCode(value.charCodeAt(start))) start++;
		if (start < separator) {
			proofkitURLCredentialPattern.lastIndex = start;
			if (proofkitURLCredentialPattern.test(value)) return true;
		}
		search = separator + 3;
	}
	return false;
}

function isProofkitASCIILetterCode(code: number): boolean {
	return code >= 65 && code <= 90 || code >= 97 && code <= 122;
}

function isProofkitSchemeCode(code: number): boolean {
	return isProofkitASCIILetterCode(code) || code >= 48 && code <= 57 || code === 43 || code === 45 || code === 46;
}

export function parseProofkitJsonReportCli<Key extends string>(
  argv: readonly string[],
  config: ProofkitJsonReportCliParseConfig<Key>,
): ProofkitJsonReportCliOptions<Key> {
  const parsed: Record<string, string | null> = { outputPath: null };
  const flagByName = new Map<string, ProofkitJsonReportCliFlag<Key>>();
  for (const flag of config.flags ?? []) {
    if (flagByName.has(flag.flag)) {
      throw new Error("duplicate CLI flag " + flag.flag);
    }
    flagByName.set(flag.flag, flag);
    parsed[flag.key] = null;
  }
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];
    if (argument === "--help") {
      (config.writeHelp ?? ((text: string) => process.stdout.write(text)))(config.helpText ?? "");
      (config.exitHelp ?? ((code: number) => process.exit(code)))(0);
    }
    if (argument === "--output") {
      if (parsed.outputPath !== null) {
        throw new Error("--output may be provided at most once");
      }
      parsed.outputPath = nextCliValue(argv, index, argument, config);
      index += 1;
      continue;
    }
    const flag = flagByName.get(argument ?? "");
    if (flag !== undefined) {
      parsed[flag.key] = nextCliValue(argv, index, argument ?? "", config);
      index += 1;
      continue;
    }
    throw new Error((config.unknownArgumentMessage ?? ((value: string) => "unknown argument " + value))(argument ?? ""));
  }
  const missing = [...flagByName.values()]
    .filter((flag) => flag.required === true && parsed[flag.key] === null)
    .map((flag) => flag.flag);
  if (missing.length > 0) {
    throw new Error((config.missingRequiredArgumentsMessage ?? ((flags: readonly string[]) => "missing required argument(s): " + flags.join(", ")))(missing));
  }
  return parsed as ProofkitJsonReportCliOptions<Key>;
}

export function parseProofkitJsonStrict(source: string): unknown {
  const scanner = new ProofkitJsonScanner(source);
  scanner.parseValue();
  scanner.skipWhitespace();
  if (!scanner.isEnd()) {
    throw new Error("invalid JSON input: multiple JSON values");
  }
  return JSON.parse(source);
}

export function readProofkitJsonReportInput(filePath: string, options: ProofkitReportInputReadOptions = {}): unknown {
  try {
    return parseProofkitJsonStrict(readProofkitBoundedTextFile(filePath, options));
  } catch (error) {
    throw new Error(formatReadFailure(filePath, error, options));
  }
}

export function readProofkitTextReportInput(filePath: string, options: ProofkitReportInputReadOptions = {}): string {
  try {
    return readProofkitBoundedTextFile(filePath, options);
  } catch (error) {
    throw new Error(formatReadFailure(filePath, error, options));
  }
}

function readProofkitBoundedTextFile(filePath: string, options: ProofkitReportInputReadOptions): string {
  const maxInputBytes = options.maxInputBytes ?? defaultMaxInputBytes;
  if (!Number.isSafeInteger(maxInputBytes) || maxInputBytes < 0) {
    throw new Error("maxInputBytes must be a non-negative safe integer");
  }
  const fd = openSync(filePath, "r");
  try {
    const stat = fstatSync(fd);
    if (!stat.isFile()) {
      throw new Error("input path must be a regular file");
    }
    if (stat.size > maxInputBytes) {
      throw new Error("input file exceeds maxInputBytes");
    }
    const chunks: Buffer[] = [];
    const chunk = Buffer.alloc(Math.min(64 * 1024, maxInputBytes + 1));
    let total = 0;
    for (;;) {
      const remaining = maxInputBytes + 1 - total;
      if (remaining <= 0) {
        throw new Error("input file exceeds maxInputBytes");
      }
      const bytesRead = readSync(fd, chunk, 0, Math.min(chunk.length, remaining), null);
      if (bytesRead === 0) {
        break;
      }
      total += bytesRead;
      if (total > maxInputBytes) {
        throw new Error("input file exceeds maxInputBytes");
      }
      chunks.push(Buffer.from(chunk.subarray(0, bytesRead)));
    }
    return decodeProofkitUTF8(Buffer.concat(chunks, total), "input file");
  } finally {
    closeSync(fd);
  }
}

export function writeProofkitJsonReportOutput(
  value: unknown,
  outputPath?: string | null,
  options: ProofkitJsonReportOutputOptions = {},
): void {
  const output = proofkitStableJsonString(value, options.jsonLayout);
  if (outputPath === null || outputPath === undefined) {
    (options.writeStdout ?? ((text: string) => process.stdout.write(text)))(output);
    return;
  }
  if (options.cwd === undefined || options.cwd.length === 0) {
    throw new Error("Proofkit cwd is required when outputPath is set");
  }
  let target: string;
  try {
    target = admitWritableOutputTarget(options.cwd, outputPath).filePath;
  } catch (error) {
    throw new Error(formatProofkitCliError(error));
  }
  writeFileAtomically(target, output);
}

export function runProofkitJsonReportCliMain(input: {
  readonly argv?: readonly string[];
  readonly run: (argv: readonly string[]) => number | Promise<number>;
  readonly writeError?: (text: string) => void;
}): Promise<void> | undefined {
  const writeError = input.writeError ?? ((text: string) => process.stderr.write(text));
  try {
    const result = input.run(input.argv ?? process.argv.slice(2));
    if (typeof result === "number") {
      process.exitCode = result;
      return undefined;
    }
    return Promise.resolve(result).then(
      (exitCode) => {
        process.exitCode = exitCode;
      },
      (error: unknown) => {
        writeError(formatProofkitCliError(error) + "\n");
        process.exitCode = 1;
      },
    );
  } catch (error) {
    writeError(formatProofkitCliError(error) + "\n");
    process.exitCode = 1;
    return undefined;
  }
}

export function runProofkitJsonCommand<T = unknown>(
  commandRoute: string,
  input: unknown,
  args: readonly string[],
  options: ProofkitCommandRunOptions,
): ProofkitJsonCommandResult<T> {
  const {child, outputFile} = runProofkitCommand(commandRoute, input, args, options);
  if (child.status !== 0 && child.stdout.trim().length === 0) {
    throw new Error(formatProofkitCliError(child.stderr.trim() || commandRoute + " failed with exit code " + String(child.status)));
  }
  const jsonText = child.stdout.trim().length === 0 && outputFile !== null ?
    readProofkitTextReportInput(requireRegularOutputTarget(outputFile)) :
    child.stdout;
  try {
    return {
      status: child.status,
      stdout: child.stdout,
      stderr: child.stderr,
      value: parseProofkitJsonStrict(jsonText) as T,
    };
  } catch (error) {
    throw new Error(formatProofkitCliError(commandRoute + " produced invalid JSON: " + formatProofkitCliError(error)));
  }
}

export function runProofkitNoInputJsonCommand<T = unknown>(
  commandRoute: string,
  args: readonly string[],
  options: ProofkitCommandRunOptions,
): ProofkitJsonCommandResult<T> {
  return runProofkitJsonCommand<T>(commandRoute, null, args, {...options, inputMode: "none"});
}

export function runProofkitTextCommand(
  commandRoute: string,
  input: unknown,
  args: readonly string[],
  options: ProofkitCommandRunOptions,
): ProofkitTextCommandResult {
  if (options.jsonLayout !== undefined) {
    throw new Error("Proofkit jsonLayout is valid only for JSON command output");
  }
  const {child, outputFile} = runProofkitCommand(commandRoute, input, args, options);
  if (child.status !== 0 && child.stdout.length === 0) {
    throw new Error(formatProofkitCliError(child.stderr.trim() || commandRoute + " failed with exit code " + String(child.status)));
  }
  const text = child.status === 0 && child.stdout.length === 0 && outputFile !== null ?
    readProofkitTextReportInput(requireRegularOutputTarget(outputFile)) :
    child.stdout;
  return {
    status: child.status,
    stdout: child.stdout,
    stderr: child.stderr,
    text,
  };
}

function runProofkitCommand(commandRoute: string, input: unknown, args: readonly string[], options: ProofkitCommandRunOptions) {
  const routeTokens = admitCommandRoute(commandRoute);
  admitRunOptions(options);
  let prepared: {readonly args: readonly string[]; readonly outputFile: string | null};
  try {
    prepared = prepareOutputArgs(options.cwd, args);
  } catch (error) {
    throw new Error(formatProofkitCliError(error));
  }
  const processArgs = options.jsonLayout === undefined ? [] : ["--json-layout", options.jsonLayout];
  const childArgs = options.inputMode === "none" ? [...processArgs, ...routeTokens, ...prepared.args] : [...processArgs, ...routeTokens, "--input", "-", ...prepared.args];
  const childResult = spawnSync(options.binaryPath, childArgs, {
    cwd: options.cwd,
    env: options.env,
    input: options.inputMode === "none" ? undefined : proofkitStableJsonString(input),
    maxBuffer: options.maxBuffer ?? defaultMaxBuffer,
  });
  if (childResult.error !== undefined) {
    throw new Error(formatProofkitCliError(childResult.error));
  }
  const child: ProofkitProcessResult = {
    status: childResult.status,
    stdout: decodeProofkitUTF8(childResult.stdout, "Proofkit stdout"),
    stderr: decodeProofkitUTF8(childResult.stderr, "Proofkit stderr"),
  };
  return {child, outputFile: prepared.outputFile};
}

function outputPathFromArgs(args: readonly string[]): string | null {
  let outputPath: string | null = null;
  for (let index = 0; index < args.length; index += 1) {
    if (args[index] === "--output") {
      if (outputPath !== null) {
        throw new Error("--output may be provided at most once");
      }
      const value = args[index + 1];
      if (value === undefined || value.startsWith("--")) {
        throw new Error("--output requires a value");
      }
      if (value === "-") {
        throw new Error("--output requires a repository-relative path other than -");
      }
      outputPath = value;
      index += 1;
    }
  }
  return outputPath;
}

function prepareOutputArgs(cwd: string, args: readonly string[]): {readonly args: readonly string[]; readonly outputFile: string | null} {
  const outputPath = outputPathFromArgs(args);
  if (outputPath === null) {
    return {args, outputFile: null};
  }
  const target = admitWritableOutputTarget(cwd, outputPath);
  const outputIndex = args.indexOf("--output");
  const canonicalArgs = args.map((argument, index) => index === outputIndex + 1 ? target.argument : argument);
  return {args: canonicalArgs, outputFile: target.filePath};
}

function admitWritableOutputTarget(cwd: string, outputPath: string): {readonly argument: string; readonly filePath: string} {
  if (isAbsolute(outputPath)) {
    throw new Error("--output requires a repository-relative path");
  }
	const root = realpathSync(cwd);
	const lexicalTarget = resolve(root, outputPath);
	assertPathInsideRoot(root, lexicalTarget, "--output must resolve inside the repository root");
	ensureWritableParent(root, dirname(lexicalTarget));
	const parent = realpathSync(dirname(lexicalTarget));
  assertPathInsideRoot(root, parent, "--output parent must resolve inside the repository root", true);
  const filePath = resolve(parent, basename(lexicalTarget));
  requireRegularOutputTarget(filePath, true);
  return {argument: relative(root, filePath), filePath};
}

function ensureWritableParent(root: string, parentPath: string): void {
  assertPathInsideRoot(root, parentPath, "--output parent must resolve inside the repository root", true);
  const relativeParent = relative(root, parentPath);
  let current = root;
  for (const component of relativeParent === "" ? [] : relativeParent.split(sep)) {
    current = resolve(current, component);
    try {
      const info = lstatSync(current);
      if (info.isSymbolicLink() || !info.isDirectory()) {
        throw new Error("--output parent components must be non-symlink directories");
      }
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
      mkdirSync(current, {mode: 0o755});
    }
  }
}

function assertPathInsideRoot(root: string, candidate: string, message: string, allowRoot = false): void {
  const relativePath = relative(root, candidate);
  if ((!allowRoot && relativePath === "") || relativePath === ".." || relativePath.startsWith(".." + sep) || isAbsolute(relativePath)) {
    throw new Error(message);
  }
}

function requireRegularOutputTarget(outputFile: string, allowMissing = false): string {
  try {
    const target = lstatSync(outputFile);
    if (target.isSymbolicLink() || !target.isFile()) {
      throw new Error("--output target must be a regular non-symlink file");
    }
  } catch (error) {
    const code = (error as NodeJS.ErrnoException).code;
    if (!(allowMissing && code === "ENOENT")) {
      throw error;
    }
  }
  return outputFile;
}

function writeFileAtomically(target: string, output: string): void {
  const temporary = target + ".tmp-" + randomUUID();
  let fd: number | null = null;
  try {
    fd = openSync(temporary, "wx", 0o600);
    writeFileSync(fd, output, {encoding: "utf8"});
    fsyncSync(fd);
    closeSync(fd);
    fd = null;
    renameSync(temporary, target);
  } catch (error) {
    if (fd !== null) {
      try { closeSync(fd); } catch { /* preserve the primary write failure */ }
    }
    try { unlinkSync(temporary); } catch { /* no temporary file to remove */ }
    throw new Error(formatProofkitCliError(error));
  }
}

class ProofkitJsonScanner {
  private index = 0;
  private readonly source: string;

  public constructor(source: string) {
    this.source = source;
  }

  public isEnd(): boolean {
    return this.index >= this.source.length;
  }

  public skipWhitespace(): void {
    while (!this.isEnd() && /\s/u.test(this.source[this.index] ?? "")) {
      this.index += 1;
    }
  }

  public parseValue(depth = 1): void {
    if (depth > maxJsonNestingDepth) {
      throw new Error("invalid JSON input: exceeds nesting depth limit");
    }
    this.skipWhitespace();
    const char = this.source[this.index];
    if (char === undefined) {
      throw new Error("invalid JSON input: unexpected end");
    }
    if (char === "{") {
      this.parseObject(depth);
      return;
    }
    if (char === "[") {
      this.parseArray(depth);
      return;
    }
    if (char === "\"") {
      this.parseString();
      return;
    }
    if (char === "-" || (char >= "0" && char <= "9")) {
      this.parseNumber();
      return;
    }
    if (this.consumeLiteral("true") || this.consumeLiteral("false") || this.consumeLiteral("null")) {
      return;
    }
    throw new Error("invalid JSON input: unexpected token");
  }

  private parseObject(depth: number): void {
    this.index += 1;
    const seen = new Set<string>();
    this.skipWhitespace();
    if (this.source[this.index] === "}") {
      this.index += 1;
      return;
    }
    while (!this.isEnd()) {
      this.skipWhitespace();
      if (this.source[this.index] !== "\"") {
        throw new Error("invalid JSON input: object key must be a string");
      }
      const key = this.parseString();
      if (seen.has(key)) {
        throw new Error("invalid JSON input: duplicate object key");
      }
      seen.add(key);
      this.skipWhitespace();
      if (this.source[this.index] !== ":") {
        throw new Error("invalid JSON input: object key must be followed by colon");
      }
      this.index += 1;
      this.parseValue(depth + 1);
      this.skipWhitespace();
      if (this.source[this.index] === "}") {
        this.index += 1;
        return;
      }
      if (this.source[this.index] !== ",") {
        throw new Error("invalid JSON input: object entries must be separated by comma");
      }
      this.index += 1;
    }
    throw new Error("invalid JSON input: unterminated object");
  }

  private parseArray(depth: number): void {
    this.index += 1;
    this.skipWhitespace();
    if (this.source[this.index] === "]") {
      this.index += 1;
      return;
    }
    while (!this.isEnd()) {
      this.parseValue(depth + 1);
      this.skipWhitespace();
      if (this.source[this.index] === "]") {
        this.index += 1;
        return;
      }
      if (this.source[this.index] !== ",") {
        throw new Error("invalid JSON input: array values must be separated by comma");
      }
      this.index += 1;
    }
    throw new Error("invalid JSON input: unterminated array");
  }

  private parseString(): string {
    if (this.source[this.index] !== "\"") {
      throw new Error("invalid JSON input: string must start with quote");
    }
    this.index += 1;
    let output = "";
    while (!this.isEnd()) {
      const char = this.source[this.index] ?? "";
      this.index += 1;
      if (char === "\"") {
        return assertProofkitScalarString(output);
      }
      if (char === "\\") {
        output += this.parseEscape();
        continue;
      }
      if (char < " ") {
        throw new Error("invalid JSON input: unescaped control character");
      }
      output += char;
    }
    throw new Error("invalid JSON input: unterminated string");
  }

  private parseEscape(): string {
    const escaped = this.source[this.index];
    this.index += 1;
    switch (escaped) {
      case "\"":
      case "\\":
      case "/":
        return escaped;
      case "b":
        return "\b";
      case "f":
        return "\f";
      case "n":
        return "\n";
      case "r":
        return "\r";
      case "t":
        return "\t";
      case "u": {
        const hex = this.source.slice(this.index, this.index + 4);
        if (!/^[0-9A-Fa-f]{4}$/u.test(hex)) {
          throw new Error("invalid JSON input: invalid unicode escape");
        }
        this.index += 4;
        return String.fromCharCode(Number.parseInt(hex, 16));
      }
      default:
        throw new Error("invalid JSON input: invalid string escape");
    }
  }

  private parseNumber(): void {
    const start = this.index;
    if (this.source[this.index] === "-") {
      this.index += 1;
    }
    if (this.source[this.index] === "0") {
      this.index += 1;
      if (isDigit(this.source[this.index])) {
        throw new Error("invalid JSON input: invalid number");
      }
    } else if (isDigitOneToNine(this.source[this.index])) {
      while (isDigit(this.source[this.index])) {
        this.index += 1;
      }
    } else {
      throw new Error("invalid JSON input: invalid number");
    }
    if (this.source[this.index] === ".") {
      this.index += 1;
      if (!isDigit(this.source[this.index])) {
        throw new Error("invalid JSON input: invalid number");
      }
      while (isDigit(this.source[this.index])) {
        this.index += 1;
      }
    }
    if (this.source[this.index] === "e" || this.source[this.index] === "E") {
      this.index += 1;
      if (this.source[this.index] === "+" || this.source[this.index] === "-") {
        this.index += 1;
      }
      if (!isDigit(this.source[this.index])) {
        throw new Error("invalid JSON input: invalid number");
      }
      while (isDigit(this.source[this.index])) {
        this.index += 1;
      }
    }
    const token = this.source.slice(start, this.index);
    const value = Number(token);
    if (!Number.isFinite(value)) {
      throw new Error("invalid JSON input: non-finite number");
    }
    if (Number.isInteger(value) && !Number.isSafeInteger(value)) {
      throw new Error("invalid JSON input: unsafe integer number");
    }
    if (jsonNumberExponentMagnitude(token) > 400) {
      throw new Error("invalid JSON input: lossy number");
    }
    if (canonicalJsonNumberToken(token) !== canonicalJsonNumberToken(String(value))) {
      throw new Error("invalid JSON input: lossy number");
    }
  }

  private consumeLiteral(literal: string): boolean {
    if (!this.source.startsWith(literal, this.index)) {
      return false;
    }
    this.index += literal.length;
    return true;
  }
}

function isDigit(value: string | undefined): boolean {
  return value !== undefined && value >= "0" && value <= "9";
}

function isDigitOneToNine(value: string | undefined): boolean {
  return value !== undefined && value >= "1" && value <= "9";
}

function jsonNumberExponentMagnitude(token: string): number {
  const exponentIndex = Math.max(token.indexOf("e"), token.indexOf("E"));
  if (exponentIndex < 0) {
    return 0;
  }
  const exponent = Number.parseInt(token.slice(exponentIndex + 1), 10);
  return Number.isFinite(exponent) ? Math.abs(exponent) : 401;
}

function canonicalJsonNumberToken(token: string): string {
  let remaining = token;
  let sign = "";
  if (remaining.startsWith("-")) {
    sign = "-";
    remaining = remaining.slice(1);
  }
  const exponentIndex = Math.max(remaining.indexOf("e"), remaining.indexOf("E"));
  let exponent = 0;
  if (exponentIndex >= 0) {
    exponent = Number.parseInt(remaining.slice(exponentIndex + 1), 10);
    remaining = remaining.slice(0, exponentIndex);
  }
  const dotIndex = remaining.indexOf(".");
  let integerPart = remaining;
  let fractionPart = "";
  if (dotIndex >= 0) {
    integerPart = remaining.slice(0, dotIndex);
    fractionPart = remaining.slice(dotIndex + 1);
  }
  const digits = integerPart + fractionPart;
  if (/^0+$/u.test(digits)) {
    return "0";
  }
  let decimalIndex = integerPart.length + exponent;
  let expanded: string;
  if (decimalIndex <= 0) {
    expanded = "0." + "0".repeat(-decimalIndex) + digits;
  } else if (decimalIndex >= digits.length) {
    expanded = digits + "0".repeat(decimalIndex - digits.length);
  } else {
    expanded = digits.slice(0, decimalIndex) + "." + digits.slice(decimalIndex);
  }
  const parts = expanded.split(".");
  const integer = (parts[0] ?? "").replace(/^0+/u, "") || "0";
  const fraction = (parts[1] ?? "").replace(/0+$/u, "");
  if (fraction !== "") {
    expanded = integer + "." + fraction;
  } else {
    expanded = integer;
  }
  return sign + expanded;
}

function nextCliValue<Key extends string>(
  argv: readonly string[],
  index: number,
  flag: string,
  config: ProofkitJsonReportCliParseConfig<Key>,
): string {
  const value = argv[index + 1];
  if (value === undefined || value.startsWith("--")) {
    throw new Error((config.missingValueMessage ?? ((name: string) => name + " requires a value"))(flag));
  }
  return value;
}

function admitCommandRoute(commandRoute: string): readonly string[] {
  const tokens = commandRoute.split(" ");
  if (tokens.length < 1 || tokens.length > 4 || tokens.some((token) => !/^[a-z0-9]+(?:-[a-z0-9]+)*$/u.test(token))) {
    throw new Error("agentic-proofkit command route must contain 1 to 4 canonical tokens");
  }
  return tokens;
}

function admitRunOptions(options: ProofkitCommandRunOptions): void {
  if (options.binaryPath.length === 0) {
    throw new Error("Proofkit binaryPath is required");
  }
  if (options.cwd.length === 0) {
    throw new Error("Proofkit cwd is required");
  }
  if (options.jsonLayout !== undefined && options.jsonLayout !== "pretty" && options.jsonLayout !== "compact") {
    throw new Error("Proofkit jsonLayout must be pretty or compact");
  }
}

function formatReadFailure(filePath: string, error: unknown, options: ProofkitReportInputReadOptions): string {
	const fixed = "<redacted-diagnostic-value>";
	const pathLabel = redactDiagnosticValue(filePath);
	const errorLabel = formatProofkitCliError(error);
	if (pathLabel === fixed || errorLabel === fixed) return fixed;
	const message = pathLabel + ": " + errorLabel;
	if (options.failureMessagePrefix === undefined) return redactDiagnosticValue(message);
	const prefix = redactDiagnosticValue(options.failureMessagePrefix);
	if (prefix === fixed) return fixed;
	return redactDiagnosticValue(prefix + ": " + message);
}

